def lcs(text1: str, text2: str) -> int:
    """
    Returns the length of the longest common subsequence of text1 and text2.
    Uses a space‑optimized dynamic programming approach with O(min(n, m)) memory.
    """
    # Ensure we iterate over the shorter string in the inner loop to save space
    if len(text1) < len(text2):
        short, long = text1, text2
    else:
        short, long = text2, text1

    m, n = len(short), len(long)

    # dp[j] will hold the LCS length for short[:i] and long[:j]
    prev = [0] * (m + 1)

    for j in range(1, n + 1):
        cur = [0] * (m + 1)
        for i in range(1, m + 1):
            if short[i - 1] == long[j - 1]:
                cur[i] = prev[i - 1] + 1
            else:
                cur[i] = max(prev[i], cur[i - 1])
        prev = cur

    return prev[m]

